import sys

data = sys.stdin.read().split()
L, C = map(int, data[:2])
grid = data[2:]

start = None
for r in range(L):
    for c in range(C):
        if grid[r][c] == 'o':
            start = (r, c)
            break
    if start is not None:
        break

def neighbors(r, c):
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < L and 0 <= nc < C and grid[nr][nc] == 'H':
            yield nr, nc

previous = start
current = next(neighbors(*start))

while True:
    adjacent = list(neighbors(*current))
    following = [pos for pos in adjacent if pos != previous]
    if not following:
        break
    previous, current = current, following[0]

print(current[0] + 1, current[1] + 1)
